// from shop.ts

export type EventShopCurrency = 'medals' | 'gems'

export type EventShopItemKind = 'towerTheme' | 'backgroundTheme' | 'song' | 'relic' | 'rotatingRelic'

export type EventShopRelicRarity = 'Rare' | 'Epic'

/** A price and the currency it is paid in. */
export interface EventShopPrice {
  price: number
  currency: EventShopCurrency
}

export interface EventShopPriceRow extends EventShopPrice {
  item: EventShopItemKind
  /** Set for the two relic kinds, which are priced by rarity; null for themes and songs. */
  rarity: EventShopRelicRarity | null
}
